#!/usr/bin/env python3
"""Validation script for pipeline outputs."""

import json
import os
import sys

try:
    import pandas as pd
except ImportError:
    print("pandas not available, falling back to csv module")
    pd = None


def load_csv(filepath):
    """Load CSV file, return None on failure."""
    try:
        if pd:
            return pd.read_csv(filepath)
        else:
            with open(filepath, 'r') as f:
                lines = f.readlines()
            if not lines:
                return None
            reader = __import__('csv').DictReader(lines)
            rows = list(reader)
            if pd:
                return pd.DataFrame(rows)
            return rows
    except Exception as e:
        return None


def check_file_exists(filepath):
    """Check if a file exists."""
    basename = os.path.basename(filepath).replace('.csv', '').replace('.json', '')
    check_name = f"file_exists_{basename}"
    if os.path.exists(filepath):
        return {"check_name": check_name, "passed": True, "message": f"File {filepath} exists."}
    return {"check_name": check_name, "passed": False, "message": f"File {filepath} does not exist."}


def check_file_not_empty(filepath):
    """Check if a file is not empty."""
    basename = os.path.basename(filepath).replace('.csv', '').replace('.json', '')
    check_name = f"file_not_empty_{basename}"
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} does not exist."}

    if filepath.endswith('.csv'):
        df = load_csv(filepath)
        if df is None:
            return {"check_name": check_name, "passed": False, "message": f"File {filepath} could not be read."}
        if pd:
            row_count = len(df)
        else:
            row_count = len(df)
        if row_count == 0:
            return {"check_name": check_name, "passed": False, "message": f"File {filepath} is empty."}
        return {"check_name": check_name, "passed": True, "message": f"File {filepath} is not empty ({row_count} rows)."}
    elif filepath.endswith('.json'):
        with open(filepath, 'r') as f:
            data = json.load(f)
        if not data:
            return {"check_name": check_name, "passed": False, "message": f"File {filepath} is empty."}
        return {"check_name": check_name, "passed": True, "message": f"File {filepath} is not empty."}

    return {"check_name": check_name, "passed": True, "message": f"File {filepath} exists and has content."}


def check_csv_columns(filepath, expected_columns):
    """Check if a CSV file has the expected columns."""
    basename = os.path.basename(filepath).replace('.csv', '')
    check_name = f"csv_columns_{basename}"
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} does not exist."}

    df = load_csv(filepath)
    if df is None:
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} could not be read."}

    if pd:
        actual_columns = list(df.columns)
    else:
        actual_columns = list(df[0].keys()) if df else []

    if set(expected_columns) == set(actual_columns) and len(expected_columns) == len(actual_columns):
        return {"check_name": check_name, "passed": True, "message": f"File {filepath} has all expected columns."}
    else:
        missing = set(expected_columns) - set(actual_columns)
        extra = set(actual_columns) - set(expected_columns)
        msg = f"File {filepath} column mismatch."
        if missing:
            msg += f" Missing: {missing}"
        if extra:
            msg += f" Extra: {extra}"
        return {"check_name": check_name, "passed": False, "message": msg}


def check_csv_row_count(filepath, expected_rows):
    """Check if a CSV file has the expected number of rows."""
    basename = os.path.basename(filepath).replace('.csv', '')
    check_name = f"row_count_{basename}"
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} does not exist."}

    df = load_csv(filepath)
    if df is None:
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} could not be read."}

    if pd:
        actual = len(df)
    else:
        actual = len(df)

    if actual == expected_rows:
        return {"check_name": check_name, "passed": True, "message": f"File {filepath} has {expected_rows} rows."}
    return {"check_name": check_name, "passed": False, "message": f"File {filepath} has {actual} rows, expected {expected_rows}."}


def check_csv_values_range(filepath, column, min_val=None, max_val=None):
    """Check if values in a column are within expected range."""
    basename = os.path.basename(filepath).replace('.csv', '')
    check_name = f"values_{basename}_{column}"
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} does not exist."}

    df = load_csv(filepath)
    if df is None:
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} could not be read."}

    if pd:
        col_values = df[column].dropna()
    else:
        col_values = [row.get(column) for row in df if row.get(column) is not None]

    if len(col_values) == 0:
        return {"check_name": check_name, "passed": False, "message": f"Column {column} in {filepath} has no non-null values."}

    if pd:
        min_actual = float(col_values.min())
        max_actual = float(col_values.max())
    else:
        min_actual = min(col_values)
        max_actual = max(col_values)

    if min_val is not None and min_actual < min_val:
        return {"check_name": check_name, "passed": False,
                f"Column {column} in {filepath} has values below {min_val} (min={min_actual})."}
    if max_val is not None and max_actual > max_val:
        return {"check_name": check_name, "passed": False,
                f"Column {column} in {filepath} has values above {max_val} (max={max_actual})."}

    return {"check_name": check_name, "passed": True,
            f"Column {column} in {filepath} has valid values (min={min_actual}, max={max_actual})."}


def check_csv_no_nulls(filepath, columns):
    """Check if specified columns have no null values."""
    basename = os.path.basename(filepath).replace('.csv', '')
    cols_short = '_'.join(columns[:2])
    check_name = f"no_nulls_{basename}_{cols_short}"
    if not os.path.exists(filepath):
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} does not exist."}

    df = load_csv(filepath)
    if df is None:
        return {"check_name": check_name, "passed": False, "message": f"File {filepath} could not be read."}

    if pd:
        for col in columns:
            if col not in df.columns:
                return {"check_name": check_name, "passed": False,
                        f"Column {col} not found in {filepath}."}
            if df[col].isna().any():
                return {"check_name": check_name, "passed": False,
                        f"Column {col} in {filepath} has null values."}
    else:
        for col in columns:
            for row in df:
                if row.get(col) is None:
                    return {"check_name": check_name, "passed": False,
                            f"Column {col} in {filepath} has null values."}

    return {"check_name": check_name, "passed": True,
            f"Columns {columns} in {filepath} have no null values."}


def main():
    """Run all validation checks."""
    checks = []

    # Define output files to validate
    output_configs = [
        {
            'filename': 't01_selected_indicators.csv',
            'expected_rows': 12,
            'expected_columns': ['indicator_id', 'indicator_name', 'theme', 'justification', 'expected_direction'],
        },
        {
            'filename': 't05_clean_stops.csv',
            'expected_rows': 407,
            'expected_columns': ['stop_id', 'stop_name', 'stop_lat', 'stop_lon'],
        },
        {
            'filename': 't08_pois_clean.csv',
            'expected_rows': 48,
            'expected_columns': ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source'],
        },
        {
            'filename': 't10_accessibility_scores.csv',
            'expected_rows': 48,
            'expected_columns': ['qid', 'label', 'poi_type', 'distance_m', 'n_departures', 'n_routes', 'accessibility_score'],
        },
        {
            'filename': 't13_city_clusters.csv',
            'expected_rows': None,
            'expected_columns': None,
        },
    ]

    for config in output_configs:
        filename = config['filename']
        filepath = os.path.join('outputs', filename)

        # Check file exists
        checks.append(check_file_exists(filepath))

        # Check file not empty
        checks.append(check_file_not_empty(filepath))

        # Check CSV columns if expected columns are known
        if config['expected_columns']:
            checks.append(check_csv_columns(filepath, config['expected_columns']))

        # Check row count if expected count is known
        if config['expected_rows'] is not None:
            checks.append(check_csv_row_count(filepath, config['expected_rows']))

    # === Additional specific checks for data quality ===

    # t01: Check expected_direction has valid values
    checks.append(check_csv_values_range('outputs/t01_selected_indicators.csv', 'expected_direction'))

    # t05: Check stop coordinates are reasonable (Alicante, Spain area)
    checks.append(check_csv_values_range('outputs/t05_clean_stops.csv', 'stop_lat', min_val=35.0, max_val=45.0))
    checks.append(check_csv_values_range('outputs/t05_clean_stops.csv', 'stop_lon', min_val=-10.0, max_val=5.0))
    checks.append(check_csv_no_nulls('outputs/t05_clean_stops.csv', ['stop_id', 'stop_name']))

    # t08: Check POI coordinates are reasonable
    checks.append(check_csv_values_range('outputs/t08_pois_clean.csv', 'latitude', min_val=35.0, max_val=45.0))
    checks.append(check_csv_values_range('outputs/t08_pois_clean.csv', 'longitude', min_val=-10.0, max_val=5.0))
    checks.append(check_csv_no_nulls('outputs/t08_pois_clean.csv', ['qid', 'poi_type']))

    # t10: Check accessibility scores are in valid range [0, 1]
    checks.append(check_csv_values_range('outputs/t10_accessibility_scores.csv', 'accessibility_score',
                                          min_val=0.0, max_val=1.0))
    # t10: Check distance is non-negative
    checks.append(check_csv_values_range('outputs/t10_accessibility_scores.csv', 'distance_m', min_val=0.0))
    # t10: Check no nulls in key columns
    checks.append(check_csv_no_nulls('outputs/t10_accessibility_scores.csv', ['qid', 'accessibility_score']))

    # t13: Check city clusters file has data
    t13_path = 'outputs/t13_city_clusters.csv'
    t13_df = load_csv(t13_path)
    if t13_df is None:
        checks.append({"check_name": "t13_city_clusters_readable", "passed": False,
                       "message": "t13_city_clusters.csv could not be read."})
    else:
        if pd:
            t13_row_count = len(t13_df)
            t13_col_count = len(t13_df.columns)
        else:
            t13_row_count = len(t13_df)
            t13_col_count = len(t13_df[0].keys()) if t13_df else 0

        checks.append({"check_name": "t13_city_clusters_has_data", "passed": t13_row_count > 0,
                       "message": f"t13_city_clusters.csv has {t13_row_count} rows and {t13_col_count} columns."})

    # Write validation summary
    summary_path = 'outputs/t14_validation_summary.json'
    with open(summary_path, 'w') as f:
        json.dump(checks, f, indent=2)

    passed_count = sum(1 for c in checks if c['passed'])
    total_count = len(checks)
    print(f"Validation complete. {passed_count}/{total_count} checks passed.")
    print(f"Summary written to {summary_path}")

    if passed_count < total_count:
        failures = [c for c in checks if not c['passed']]
        print(f"\nFailed checks:")
        for fail in failures:
            print(f"  - {fail['check_name']}: {fail['message']}")

    return 0 if passed_count == total_count else 1


if __name__ == '__main__':
    sys.exit(main())
